-- PostgreSQL; Study assumptions: orders(id bigint PRIMARY KEY,
-- order_key text NOT NULL, updated_at timestamptz); latest version survives.
BEGIN;
WITH numbered AS (
  SELECT id, ROW_NUMBER() OVER (
    PARTITION BY order_key ORDER BY updated_at DESC NULLS LAST, id DESC
  ) AS version_position
  FROM orders
)
DELETE FROM orders AS o
USING numbered AS n
WHERE o.id = n.id AND n.version_position > 1
RETURNING o.*;
ROLLBACK;

-- PostgreSQL; Study assumptions: parent(id bigint PRIMARY KEY),
-- child(id bigint PRIMARY KEY, parent_id bigint); NULL means optional.
BEGIN;
SELECT c.* FROM child AS c
WHERE c.parent_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM parent AS p WHERE p.id = c.parent_id);
DELETE FROM child AS c
WHERE c.parent_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM parent AS p WHERE p.id = c.parent_id)
RETURNING c.*;
ROLLBACK;

