-- PostgreSQL; Study assumptions: employees(id bigint PRIMARY KEY,
-- salary numeric, status text). Dedicated audit object names are unused.
BEGIN;
CREATE TABLE salary_audit (
  employee_id bigint, old_salary numeric, new_salary numeric,
  old_status text, new_status text, changed_at timestamptz, changed_by text
);
CREATE FUNCTION audit_sensitive_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.salary IS DISTINCT FROM NEW.salary
     OR OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO salary_audit
    VALUES (NEW.id, OLD.salary, NEW.salary, OLD.status, NEW.status,
            clock_timestamp(), current_user);
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER sensitive_change_audit
AFTER UPDATE ON employees
FOR EACH ROW EXECUTE FUNCTION audit_sensitive_change();
UPDATE employees SET status = 'active' WHERE id = 1;
SELECT * FROM salary_audit;
ROLLBACK;

-- PostgreSQL; Study assumptions: products(id bigint PRIMARY KEY, price numeric),
-- staged_prices(product_id bigint PRIMARY KEY, price numeric).
BEGIN;
UPDATE products AS p
SET price = s.price
FROM staged_prices AS s
WHERE p.id = s.product_id AND p.price IS DISTINCT FROM s.price
RETURNING p.id, p.price;
ROLLBACK;

-- PostgreSQL; Study assumptions: items(id bigint PRIMARY KEY, payload text);
-- delete positions 3,6,9,... in ascending ID order.
BEGIN;
WITH numbered AS (
  SELECT id, ROW_NUMBER() OVER (ORDER BY id) AS position FROM items
)
DELETE FROM items AS i
USING numbered AS n
WHERE i.id = n.id AND n.position % 3 = 0
RETURNING i.*;
ROLLBACK;

-- PostgreSQL; Study assumptions: public.sales(amount numeric) exists.
-- Only that table and column are permitted by this demonstration.
CREATE OR REPLACE FUNCTION pg_temp.count_above(
  p_table regclass, p_column text, p_min numeric
) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE result_count bigint;
BEGIN
  IF p_table <> 'public.sales'::regclass OR p_column <> 'amount' THEN
    RAISE EXCEPTION 'Unsupported table or column';
  END IF;
  EXECUTE format('SELECT count(*) FROM %s WHERE %I > $1', p_table, p_column)
    INTO result_count USING p_min;
  RETURN result_count;
END;
$$;
SELECT pg_temp.count_above('public.sales'::regclass, 'amount', 100);

-- PostgreSQL; Study assumptions: users(id bigint PRIMARY KEY,
-- email text NOT NULL, deleted_at timestamptz); active emails are unique.
BEGIN;
CREATE UNIQUE INDEX users_active_email_study_idx
  ON users(email) WHERE deleted_at IS NULL;
UPDATE users
SET deleted_at = COALESCE(deleted_at, CURRENT_TIMESTAMP)
WHERE id = 7
RETURNING id, deleted_at;
SELECT id, email FROM users WHERE deleted_at IS NULL ORDER BY id;
ROLLBACK;

-- PostgreSQL; Study assumptions: input_values(n integer);
-- invalid, negative, over-width, and NULL values yield NULL.
